// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.reasoningimport timber.log.Timberimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.ReasoningStepimport com.roshan.persona.cognitive.model.ReasoningTraceimport com.roshan.persona.cognitive.model.SubTaskimport com.roshan.persona.cognitive.model.VerificationResultimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.persona.core.PersonaProfileimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Reasoning Engine (Module 7 v2 — Step 7.4). * * The main cognitive reasoning engine. Combines: *  1. [ChainOfThought] — step-by-step LLM reasoning. *  2. [SelfCorrector] — rule-based + LLM-based verification. *  3. Multi-perspective analysis (pragmatic + creative + critical). * * ## Flow * * ``` * 1. ChainOfThought.generate(query, persona, targetSteps) *    → List<ReasoningStep> * 2. Assemble into ReasoningTrace (steps + finalAnswer + confidence) * 3. SelfCorrector.verify(trace, constraints, persona) *    → Verified: return trace *    → NeedsCorrection: retry (max 3 attempts) *       → On retry: generate new trace with correction hint *       → If retry succeeds: show BOTH (originalAnswer + correctedAnswer) per Q2 *    → Failed: return trace with reduced confidence * 4. Return final ReasoningTrace * ``` * * ## Adaptive depth (per Q5) * * The target number of reasoning steps is adaptive: *  - Simple queries → [CognitiveConfig.minReasoningSteps] (3) *  - Complex queries → [CognitiveConfig.maxReasoningSteps] (10) *  - Determined by [estimateComplexity] * * ## Self-correction with "show both" (per Q2) * * When self-correction changes the answer, the trace records: *  - `correctionApplied = true` *  - `originalAnswer` = the pre-correction answer *  - `finalAnswer` = the corrected answer *  - `alternativesConsidered` includes the original answer * * The UI (Module 16) shows: "I initially thought X, but on reflection, Y is * better because..." — building trust through humility. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ReasoningEngine</a> */class ReasoningEngine(    private val chainOfThought: ChainOfThought,    private val selfCorrector: SelfCorrector,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Reason through [query] and produce a [ReasoningTrace].     *     * @param query the user's question or goal.     * @param persona the active persona (affects reasoning style + temperature).     * @param constraints constraints the answer must satisfy.     * @param subTasks optional sub-tasks from TaskPlanner (for multi-step queries).     * @param context additional context (memory recall, ambient snapshot).     * @return a reasoning trace with steps + final answer + confidence.     */    suspend fun reason(        query: String,        persona: PersonaProfile,        constraints: List<Constraint> = emptyList(),        subTasks: List<SubTask>? = null,        context: String = "",    ): ReasoningTrace = withContext(dispatcher) {        val startTime = System.nanoTime()        val targetSteps = estimateComplexity(query, subTasks)        Timber.tag(TAG).d("Reasoning: query='$query', targetSteps=$targetSteps, persona=${persona.id}")        // 1. Generate initial chain-of-thought.        val steps = chainOfThought.generate(query, persona, targetSteps, context)        if (steps.isEmpty()) {            return@withContext ReasoningTrace(                steps = listOf(ReasoningStep(                    thought = "I was unable to reason about this query.",                    action = "Returning default response",                    observation = "No reasoning steps generated",                    confidence = 0.1f,                )),                finalAnswer = "I'm sorry, I couldn't reason through that. Could you rephrase?",                confidence = 0.1f,                timeMs = (System.nanoTime() - startTime) / 1_000_000,            )        }        // 2. Assemble initial trace.        var trace = assembleTrace(steps, query, persona, startTime)        var attempts = 0        var originalAnswer: String? = null        val alternatives = mutableListOf<String>()        // 3. Self-correction loop (max 3 attempts).        while (attempts < config.maxCorrectionAttempts) {            val verification = selfCorrector.verify(trace, constraints, persona)            when (verification) {                is VerificationResult.Verified -> {                    // Reasoning is sound — return trace (with correction info if applicable).                    return@withContext if (originalAnswer != null) {                        trace.copy(                            correctionApplied = true,                            originalAnswer = originalAnswer,                            alternativesConsidered = alternatives,                        )                    } else {                        trace                    }                }                is VerificationResult.NeedsCorrection -> {                    attempts++                    Timber.tag(TAG).d("Self-correction attempt $attempts: ${verification.issue}")                    // Save original answer for "show both" (Q2).                    if (originalAnswer == null) {                        originalAnswer = trace.finalAnswer                    }                    alternatives.add(trace.finalAnswer)                    // Regenerate with correction hint.                    val correctedSteps = chainOfThought.generate(                        query = "$query\n\nCorrection needed: ${verification.issue}. Fix: ${verification.suggestedFix}",                        persona = persona,                        targetSteps = targetSteps,                        context = context,                    )                    if (correctedSteps.isEmpty()) break  // can't correct → return current trace                    trace = assembleTrace(correctedSteps, query, persona, startTime)                }                is VerificationResult.Failed -> {                    // Fundamentally flawed — return with reduced confidence.                    Timber.tag(TAG).w("Verification failed: ${verification.reason}")                    return@withContext trace.copy(                        confidence = (trace.confidence * 0.3f).coerceIn(0.05f, 0.5f),                        correctionApplied = originalAnswer != null,                        originalAnswer = originalAnswer,                        alternativesConsidered = alternatives,                    )                }            }        }        // Max attempts reached — return best trace with reduced confidence.        Timber.tag(TAG).w("Max correction attempts ($attempts) reached — returning best trace.")        trace.copy(            confidence = (trace.confidence * 0.5f).coerceIn(0.1f, 0.7f),            correctionApplied = originalAnswer != null,            originalAnswer = originalAnswer,            alternativesConsidered = alternatives,        )    }    /**     * Estimate the complexity of [query] to determine reasoning depth.     *     * Simple queries → [CognitiveConfig.minReasoningSteps] (3).     * Complex queries → [CognitiveConfig.maxReasoningSteps] (10).     *     * Heuristic: word count + question type + presence of sub-tasks.     */    internal fun estimateComplexity(query: String, subTasks: List<SubTask>?): Int {        // If sub-tasks exist, this is a complex multi-step query.        if (subTasks != null && subTasks.isNotEmpty()) {            return config.maxReasoningSteps        }        val wordCount = query.split(Regex("\\s+")).filter { it.isNotBlank() }.size        val hasComplexKeywords = COMPLEX_KEYWORDS.any { query.lowercase().contains(it) }        return when {            wordCount > 20 || hasComplexKeywords -> (config.minReasoningSteps + config.maxReasoningSteps) / 2            wordCount > 10 -> config.minReasoningSteps + 2            else -> config.minReasoningSteps        }.coerceIn(config.minReasoningSteps, config.maxReasoningSteps)    }    /**     * Assemble reasoning steps into a [ReasoningTrace].     *     * The final answer is derived from the last step's observation (or thought     * if observation is "N/A"). Confidence is the average of step confidences.     */    private fun assembleTrace(        steps: List<ReasoningStep>,        query: String,        persona: PersonaProfile,        startTime: Long,    ): ReasoningTrace {        // Derive final answer from the last step.        val lastStep = steps.last()        val finalAnswer = if (lastStep.observation.isNotBlank() && lastStep.observation != "N/A") {            lastStep.observation        } else {            lastStep.thought        }        // Average confidence across all steps.        val avgConfidence = steps.map { it.confidence }.average().toFloat().coerceIn(0f, 1f)        return ReasoningTrace(            steps = steps,            finalAnswer = finalAnswer,            confidence = avgConfidence,            timeMs = (System.nanoTime() - startTime) / 1_000_000,            correlationId = CorrelationId.generate(),        )    }    private companion object {        private const val TAG = "ReasoningEngine"        /** Keywords that indicate a complex query needing deeper reasoning. */        private val COMPLEX_KEYWORDS = listOf(            "compare", "analyze", "evaluate", "should i", "plan", "design",            "optimize", "trade-off", "pros and cons", "recommend", "strategy",        )    }}
